Tool: GITHUB_IS_REPOSITORY_STARRED_BY_THE_USER
Description: Use to determine if the authenticated user has starred a specific GitHub repository, which is confirmed by an HTTP 204 status (resulting in an empty dictionary in the response data); the action fails (e.g., HTTP 404) if the repository is not starred or does not exist.
Parameters: {
  "type": "object",
  "title": "CheckIfRepoStarredByAuthUserRequest",
  "required": [
    "owner",
    "repo"
  ],
  "properties": {
    "repo": {
      "type": "string",
      "title": "Repo",
      "examples": [
        "Spoon-Knife",
        "my-project"
      ],
      "description": "The name of the repository, without the `.git` extension. This name is not case sensitive. Please provide a value of type string. This parameter is required.",
      "human_parameter_name": "Repository name",
      "human_parameter_description": "The exact repository you want to check for a star. Provide its short name (without .git) so we know which repo to look up."
    },
    "owner": {
      "type": "string",
      "title": "Owner",
      "examples": [
        "octocat",
        "example-org"
      ],
      "description": "The account owner of the repository (e.g., a user or organization). This name is not case sensitive. Please provide a value of type string. This parameter is required.",
      "human_parameter_name": "Account owner",
      "human_parameter_description": "The GitHub user or organization that owns the repository you want to check. Enter their username or org name so we can find the right repo."
    }
  },
  "description": "Request model for specifying the repository to check for a star by the authenticated user."
}
